WITH source_unioned AS (
    SELECT customer_id AS customer_bk,
           '{{ run_started_at }}'::TIMESTAMP AS load_dts,
           'crm.customers' AS record_source
    FROM {{ ref('stg_crm__customers') }}
    WHERE customer_id IS NOT NULL
),
hashed AS (
    SELECT {{ dv_hash_bk(['customer_bk']) }} AS customer_hk,
           customer_bk, load_dts, record_source
    FROM source_unioned
),
deduped AS (
    SELECT * FROM hashed
    QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_hk ORDER BY load_dts) = 1
)
SELECT * FROM deduped
